  "help.seeanythingrecordedagainstyouraccountand": "Sieh Einträge zu deinem Konto und lege Einspruch ein, wenn du sie für falsch hältst.",
  "help.topicAskaquestionabouthowtheapp": "Stelle im Chat eine Frage zur App. Chatnachrichten kosten die dort angezeigten Credits.",
  "help.topicAskinchat": "Im Chat fragen",
  "helpGuides.all": "Alle Anleitungen",
  "helpGuides.content.credits.l1": "Credits und Abrechnung",
  "helpGuides.content.credits.l2": "Erstattungsrichtlinie",
  "helpGuides.content.credits.s1.body": "Bilder, Video, Audio und Sprache verbrauchen dieselben Credits. Jedes Modell zeigt seinen Preis, bevor du generierst.",
  "helpGuides.content.credits.s1.title": "Ein Guthaben für alles",
  "helpGuides.content.credits.s2.body": "Die 10 Anmelde-Credits werden zuerst verbraucht und verfallen 90 Tage nach der Gutschrift, wenn sie ungenutzt bleiben.",
  "helpGuides.content.credits.s2.title": "Kostenlose Credits",
  "helpGuides.content.credits.s3.body": "Credit-Pakete kaufst du auf der Seite Credits über Stripe. Gekaufte Credits verfallen nie.",
  "helpGuides.content.credits.s3.title": "Credits kaufen",
  "helpGuides.content.credits.s4.body": "Schlägt eine Generierung fehl, werden ihre Credits automatisch deinem Guthaben wieder gutgeschrieben. Die Bibliothek zeigt die fehlgeschlagene Generierung und ihre Erstattung.",
  "helpGuides.content.credits.s4.title": "Wenn etwas fehlschlägt",
  "helpGuides.content.credits.s5.body": "Ein Konto kann 10 Generierungen pro Minute starten. Alles darüber wird abgelehnt, ohne dass dir etwas berechnet wird.",
  "helpGuides.content.credits.s5.title": "Grenzen",
  "helpGuides.content.credits.summary": "Ein Guthaben, Preise vorab, automatische Erstattungen.",
  "helpGuides.content.credits.title": "So funktionieren Credits und Erstattungen",
  "helpGuides.content.first-generation.l1": "Studio öffnen",
  "helpGuides.content.first-generation.l2": "Alle Preise ansehen",
  "helpGuides.content.first-generation.s1.body": "Gehe zu Erstellen. Melde dich vorher an oder erstelle ein Konto; neue Konten erhalten einmalig 10 kostenlose Credits, sobald die E-Mail-Adresse bestätigt ist.",
  "helpGuides.content.first-generation.s1.title": "Studio öffnen",
  "helpGuides.content.first-generation.s2.body": "Die Liste rechts zeigt jedes Modell mit seinem Preis in Credits. Bild-, Video- und Audiomodelle verbrauchen alle dasselbe Guthaben.",
  "helpGuides.content.first-generation.s2.title": "Ein Modell wählen",
  "helpGuides.content.first-generation.s3.body": "Beschreibe, was du sehen möchtest. Bei einem Video gibst du an, was sich bewegt und wie sich die Kamera bewegt.",
  "helpGuides.content.first-generation.s3.title": "Den Prompt schreiben",
  "helpGuides.content.first-generation.s4.body": "Die Gesamtsumme steht über dem Generieren-Button, bevor du ihn drückst. Ein 10-Sekunden-Clip kostet doppelt so viel wie ein 5-Sekunden-Clip, und wenn du mehrere Bilder wählst, wird der Preis mit der Anzahl multipliziert.",
  "helpGuides.content.first-generation.s4.title": "Die Kosten prüfen",
  "helpGuides.content.first-generation.s5.body": "Die Credits werden abgebucht, wenn du auf Generieren drückst. Schlägt die Generierung fehl, werden sie automatisch deinem Guthaben wieder gutgeschrieben.",
  "helpGuides.content.first-generation.s5.title": "Generieren",
  "helpGuides.content.first-generation.summary": "Modell wählen, Preis sehen, generieren.",
  "helpGuides.content.first-generation.title": "Dein erstes Bild oder Video erstellen",
  "helpGuides.content.library.l1": "Die Library öffnen",
  "helpGuides.content.library.s1.body": "Jede Generierung wird aufgelistet, auch fehlgeschlagene, sodass du sehen kannst, was erstattet wurde.",
  "helpGuides.content.library.s1.title": "Die Library öffnen",
  "helpGuides.content.library.s2.body": "Filtere nach Status und nach Typ (Bilder, Video, Audio) und wechsle zwischen Raster- und Listenansicht.",
  "helpGuides.content.library.s2.title": "Filtern",
  "helpGuides.content.library.s3.body": "Der Stern auf einer Karte fügt sie zu Favourites hinzu. Favourites werden in dem Browser gespeichert, in dem du sie markiert hast.",
  "helpGuides.content.library.s3.title": "Favoriten mit einem Stern markieren",
  "helpGuides.content.library.s4.body": "Generierte Dateien werden nicht für immer gespeichert. Jede Karte zeigt, wie lange ihre Datei aufbewahrt wird; lade alles herunter, was du brauchst, bevor diese Zeit abläuft.",
  "helpGuides.content.library.s4.title": "Herunterladen, was du behalten willst",
  "helpGuides.content.library.summary": "Filtern, markieren und herunterladen aus deiner Library.",
  "helpGuides.content.library.title": "Finden und behalten, was du erstellt hast",
  "helpGuides.content.templates.l1": "Vorlagen durchstöbern",
  "helpGuides.content.templates.s1.body": "Filtere nach Kategorie. Jede Karte zeigt das Modell, auf dem die Vorlage läuft, und den Preis.",
  "helpGuides.content.templates.s1.title": "Die Vorlagen durchstöbern",
  "helpGuides.content.templates.s2.body": "Die Vorlagenseite zeigt den vollständigen Prompt, die Kosten und, falls das Modell etwas braucht, was du hochladen musst.",
  "helpGuides.content.templates.s2.title": "Eine Vorlage öffnen",
  "helpGuides.content.templates.s3.body": "Vorlage verwenden öffnet das Studio mit ausgefülltem Prompt, Modell und Seitenverhältnis. Es wird nichts berechnet, bis du auf Generieren drückst.",
  "helpGuides.content.templates.s3.title": "Verwenden",
  "helpGuides.content.templates.s4.body": "Passe den Prompt an, bevor du generierst. Die Vorlage ist ein Ausgangspunkt, kein festes Rezept.",
  "helpGuides.content.templates.s4.title": "Mach sie zu deiner eigenen",
  "helpGuides.content.templates.summary": "Fertiger Prompt, Modell und Seitenverhältnis mit einem Klick.",
  "helpGuides.content.templates.title": "Mit einer Vorlage starten",
  "helpGuides.content.your-own-files.l1": "Die Tools ansehen",
  "helpGuides.content.your-own-files.l2": "Nutzungsrichtlinie",
  "helpGuides.content.your-own-files.s1.body": "Die Seite Tools listet jedes Modell auf, das von deiner eigenen Datei ausgeht, was es braucht und was es kostet.",
  "helpGuides.content.your-own-files.s1.title": "Ein Tool wählen",
  "helpGuides.content.your-own-files.s2.body": "Bilder können PNG, JPEG oder WebP sein, bis 20 MB. Videos sind MP4, bis 100 MB. Sprache ist MP3 oder WAV, bis 20 MB.",
  "helpGuides.content.your-own-files.s2.title": "Deine Datei hinzufügen",
  "helpGuides.content.your-own-files.s3.body": "Bei einem Bild kannst du über Aus Bibliothek wählen eines auswählen, das du bereits generiert hast, statt es erneut hochzuladen.",
  "helpGuides.content.your-own-files.s3.title": "Oder ein Ergebnis wiederverwenden",
  "helpGuides.content.your-own-files.s4.body": "Setze das Häkchen bei der Erklärung, dass dir die Datei gehört oder dass alle erkennbaren Personen darin zugestimmt haben. Die Erklärung wird mit der Generierung gespeichert.",
  "helpGuides.content.your-own-files.s4.title": "Bestätigen, dass du sie nutzen darfst",
  "helpGuides.content.your-own-files.s5.body": "Preis und Erstattung bei Fehlschlag funktionieren genauso wie bei jeder anderen Generierung.",
